(()=>{const data=window.MindscapeResearch||[],root=document.getElementById('research-list');const depth=document.body.classList.contains('overview-page')?'../':'../../';const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let category='All',limit=9;
if(root){const search=document.getElementById('research-search'),topic=document.getElementById('research-topic'),sort=document.getElementById('research-sort'),more=document.getElementById('load-more');function render(){let rows=data.filter(r=>(document.getElementById('research-version').value==='All'||r.version===document.getElementById('research-version').value)&&(category==='All'||r.category===category)&&(topic.value==='All'||r.topic===topic.value)&&(`${r.title} ${r.description}`).toLowerCase().includes(search.value.toLowerCase()));if(sort.value!=='featured')rows.sort((a,b)=>a.title.localeCompare(b.title)*(sort.value==='az'?1:-1));root.innerHTML=rows.slice(0,limit).map((r,i)=>`<a class="archive-entry" href="${esc(r.url||depth+'assets/reports/'+r.file)}"><div class="entry-meta">${esc(r.category)}<small>${esc(r.topic)} · ${r.format==='Markdown'?r.version+' · Markdown':r.pages+' '+(r.pages===1?'page':'pages')}</small></div><div class="entry-art abstract-art ${['orbit','wave','trace'][i%3]}" aria-hidden="true"><span></span></div><div class="entry-copy"><h2>${esc(r.title)} ↗</h2><p>${esc(r.description)}</p></div></a>`).join('')||'<p>No documents match these filters.</p>';more.hidden=limit>=rows.length;document.getElementById('result-count').textContent=`${rows.length} documents found. Showing ${Math.min(limit,rows.length)}.`}document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;limit=9;document.querySelectorAll('[data-category]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render()}));[search,topic,sort,document.getElementById("research-version")].forEach(e=>e.addEventListener(e===search?'input':'change',()=>{limit=9;render()}));more.addEventListener('click',()=>{limit+=9;render()});document.getElementById('filter-toggle').addEventListener('click',e=>{const panel=document.getElementById('filter-panel');panel.hidden=!panel.hidden;e.currentTarget.setAttribute('aria-expanded',String(!panel.hidden));if(!panel.hidden)search.focus()});document.getElementById('clear-filters').addEventListener('click',()=>{search.value='';topic.value='All';document.getElementById('research-version').value='All';limit=9;render()});document.getElementById('media-toggle').addEventListener('click',e=>{const show=root.classList.toggle('show-media');e.currentTarget.setAttribute('aria-pressed',String(show));e.currentTarget.setAttribute('aria-label',show?'Hide card media':'Show card media')});render()}
const reports=document.getElementById('reports-list');if(reports){let count=10;function draw(){reports.innerHTML=data.slice(0,count).map(r=>`<a class="report-row" href="${esc(r.url||depth+'assets/reports/'+r.file)}"><h3>${esc(r.title)}</h3><p>${esc(r.topic)} · ${r.format==='Markdown'?r.version+' · Markdown':r.pages+' '+(r.pages===1?'page':'pages')} | ${esc(r.description)}</p><span class="text-link">Read report ↗</span></a>`).join('');document.getElementById('reports-more').hidden=count>=data.length}document.getElementById('reports-more').addEventListener('click',()=>{count+=10;draw()});draw();let slide=0;const slides=[['V3: verified three-domain integration','v3/v3-integration.md'],['V3.1 physics: stability pilot NO-GO','v3/v3-1-physics.md'],['V3 mathematical learning: findings and limits','v3/v3-mathematics.md'],['Historical V1/V2 research and security report','Mindscape-Research-Report.pdf'],['Verified progress and bounded mechanism findings','reports/research_v2--scientific_report.pdf'],['Scientific gap closure: replication and telemetry','reports/research_v2--gap_closure.pdf']];function move(step){slide=(slide+step+slides.length)%slides.length;document.getElementById('featured-title').textContent=slides[slide][0];document.getElementById('featured-report').href=depth+'assets/'+slides[slide][1];document.getElementById('slide-count').textContent=`${slide+1} / ${slides.length}`}document.getElementById('previous-report').addEventListener('click',()=>move(-1));document.getElementById('next-report').addEventListener('click',()=>move(1))}
})();
